module TravelCardOptimizer(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [7:0] a,\n    input wire [7:0] b,\n    input wire [3:0] k,\n    input wire [15:0] f,\n    input wire [2:0] n,\n    input wire [31:0] stop1,\n    input wire [31:0] stop2,\n    output reg [15:0] total_cost,\n    output reg done\n);\n\n    // Internal memory for route table (max 8 routes)\n    reg [31:0] route_start [0:7];\n    reg [31:0] route_end [0:7];\n    reg [15:0] route_cost [0:7];\n    reg [2:0] route_count;\n\n    // State machine states\n    localparam [3:0] IDLE = 4'd0;\n    localparam [3:0] PROCESS_TRIP = 4'd1;\n    localparam [3:0] UPDATE_ROUTES = 4'd2;\n    localparam [3:0] SORT_INIT = 4'd3;\n    localparam [3:0] SORT_COMPARE = 4'd4;\n    localparam [3:0] SORT_SWAP = 4'd5;\n    localparam [3:0] SORT_NEXT = 4'd6;\n    localparam [3:0] APPLY_CARDS = 4'd7;\n    localparam [3:0] FINISH = 4'd8;\n\n    reg [3:0] state;\n    reg [2:0] trip_idx;\n    reg [31:0] last_end_stop;\n    reg [31:0] curr_start, curr_end;\n    reg [15:0] current_cost;\n    reg [2:0] sort_i, sort_j;\n    reg [2:0] card_idx;\n    reg [15:0] temp_cost;\n    integer i;\n\n    // Helper: Find or create route\n    function [2:0] find_route;\n        input [31:0] s1, s2;\n        reg [31:0] min_stop, max_stop;\n        integer r;\n        begin\n            min_stop = (s1 < s2) ? s1 : s2;\n            max_stop = (s1 < s2) ? s2 : s1;\n            find_route = 3'd7;\n            for (r = 0; r < route_count; r = r + 1) begin\n                if (route_start[r] == min_stop && route_end[r] == max_stop)\n                    find_route = r;\n            end\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            total_cost <= 16'd0;\n            route_count <= 3'd0;\n            trip_idx <= 3'd0;\n            last_end_stop <= 32'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                route_cost[i] <= 16'd0;\n                route_start[i] <= 32'd0;\n                route_end[i] <= 32'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start && n > 3'd0) begin\n                        state <= PROCESS_TRIP;\n                        trip_idx <= 3'd0;\n                        route_count <= 3'd0;\n                        last_end_stop <= 32'd0;\n                        total_cost <= 16'd0;\n                    end\n                end\n                \n                PROCESS_TRIP: begin\n                    curr_start <= stop1;\n                    curr_end <= stop2;\n                    current_cost <= (stop1 == last_end_stop) ? {8'd0, b} : {8'd0, a};\n                    state <= UPDATE_ROUTES;\n                end\n                \n                UPDATE_ROUTES: begin\n                    total_cost <= total_cost + current_cost;\n                    \n                    reg [2:0] route_idx;\n                    route_idx = find_route(curr_start, curr_end);\n                    \n                    if (route_idx < 3'd7) begin\n                        route_cost[route_idx] <= route_cost[route_idx] + current_cost;\n                    end else if (route_count < 3'd7) begin\n                        if (curr_start < curr_end) begin\n                            route_start[route_count] <= curr_start;\n                            route_end[route_count] <= curr_end;\n                        end else begin\n                            route_start[route_count] <= curr_end;\n                            route_end[route_count] <= curr_start;\n                        end\n                        route_cost[route_count] <= current_cost;\n                        route_count <= route_count + 1;\n                    end\n                    \n                    last_end_stop <= curr_end;\n                    \n                    if (trip_idx + 1 >= n) begin\n                        state <= SORT_INIT;\n                        sort_i <= 3'd0;\n                        sort_j <= 3'd0;\n                    end else begin\n                        state <= PROCESS_TRIP;\n                        trip_idx <= trip_idx + 1;\n                    end\n                end\n                \n                SORT_INIT: begin\n                    sort_i <= 3'd0;\n                    sort_j <= 3'd0;\n                    state <= SORT_COMPARE;\n                end\n                \n                SORT_COMPARE: begin\n                    if (sort_j < route_count - sort_i - 1) begin\n                        if (route_cost[sort_j] < route_cost[sort_j + 1]) begin\n                            state <= SORT_SWAP;\n                        end else begin\n                            state <= SORT_NEXT;\n                        end\n                    end else begin\n                        sort_i <= sort_i + 1;\n                        sort_j <= 3'd0;\n                        if (sort_i >= route_count - 2) begin\n                            state <= APPLY_CARDS;\n                            card_idx <= 3'd0;\n                        end else begin\n                            state <= SORT_COMPARE;\n                        end\n                    end\n                end\n                \n                SORT_SWAP: begin\n                    temp_cost <= route_cost[sort_j];\n                    route_cost[sort_j] <= route_cost[sort_j + 1];\n                    route_cost[sort_j + 1] <= temp_cost;\n                    route_start[sort_j] <= route_start[sort_j + 1];\n                    route_start[sort_j + 1] <= route_start[sort_j];\n                    route_end[sort_j] <= route_end[sort_j + 1];\n                    route_end[sort_j + 1] <= route_end[sort_j];\n                    state <= SORT_NEXT;\n                end\n                \n                SORT_NEXT: begin\n                    sort_j <= sort_j + 1;\n                    state <= SORT_COMPARE;\n                end\n                \n                APPLY_CARDS: begin\n                    if (card_idx < route_count && card_idx < k) begin\n                        if (route_cost[card_idx] > f) begin\n                            total_cost <= total_cost - (route_cost[card_idx] - f);\n                        end\n                        card_idx <= card_idx + 1;\n                    end else begin\n                        state <= FINISH;\n                    end\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule